mapper.select:
select child.*, parent.code as parentCode, parent.name as parentName from book_subject child left join book_subject parent on child.parent_id = parent.id and parent.deleted = 'n' and parent.book_id = #{Dto.bookId} and (parent.is_auxiliary <> 1 OR parent.is_auxiliary IS NULL) where child.deleted = 'n' and child.book_id = #{Dto.bookId}
and child.status = #{Dto.status}
and (child.is_auxiliary <> 1 OR child.is_auxiliary IS NULL)
and child.category = #{Dto.category}
and child.code like CONCAT(#{Dto.code}, '%')
and child.name like CONCAT('%', #{Dto.name}, '%')
order by child.code ASC

SELECT s.id, s.parent_id, s.`code`, s.`name`, s.direction, s.category, s.id_path, i.debit_amount, i.credit_amount, i.subject_balance as balance FROM book_subject s LEFT JOIN ( SELECT i_inner.* FROM voucher_item i_inner INNER JOIN ( SELECT subject_code, ${params.countType}(id) AS max_id FROM voucher_item WHERE deleted = 'n'
AND YEAR(voucher_date) = #{params.year}
AND MONTH(voucher_date) = #{params.month}
AND QUARTER(voucher_date) = #{params.quarter}
GROUP BY subject_code ) latest ON i_inner.subject_code = latest.subject_code AND i_inner.id = latest.max_id ) i ON s.`code` = i.subject_code LEFT JOIN voucher v ON i.voucher_id = v.id AND v.deleted = 'n' and v.status in ('reviewing', 'completed') WHERE s.book_id = #{params.bookId} AND s.deleted = 'n' and (s.is_auxiliary <> 1 OR s.is_auxiliary IS NULL) ORDER BY s.category, s.code
